def get_filtered_average(data, column, filter_column=None, filter_value=None):
    if filter_column and filter_value:
        filtered_data = data[data[filter_column] == filter_value]
        return filtered_data[column].mean()
    return data[column].mean()

# Use the function with different parameters
print(f"Overall average score: {get_filtered_average(data, 'test_score')}")
