import pandas as pd
import numpy as np

def advanced_attention_analysis(data, column='test_score', operation='mean', *args, **kwargs):
    # Make a copy of the data to avoid modifying the original
    filtered_data = data.copy()

    # Process each filter in kwargs
    for key, value in kwargs.items():
        if key.endswith('_gt'):
            # Greater than filter (e.g., phone_duration_gt=30)
            col_name = key.replace('_gt', '')
            if col_name in filtered_data.columns:
                filtered_data = filtered_data[filtered_data[col_name] > value]
            elif col_name == 'phone_duration' and 'phone_duration (sec)' in filtered_data.columns:
                filtered_data = filtered_data[filtered_data['phone_duration (sec)'] > value]
        elif key.endswith('_lt'):
            # Less than filter
            col_name = key.replace('_lt', '')
            if col_name in filtered_data.columns:
                filtered_data = filtered_data[filtered_data[col_name] < value]
            elif col_name == 'phone_duration' and 'phone_duration (sec)' in filtered_data.columns:
                filtered_data = filtered_data[filtered_data['phone_duration (sec)'] < value]
        else:
            # Equality filter
            if key in filtered_data.columns:
                filtered_data = filtered_data[filtered_data[key] == value]

    # Ensure the column exists
    if column not in filtered_data.columns and column == 'phone_duration' and 'phone_duration (sec)' in filtered_data.columns:
        column = 'phone_duration (sec)'

    # Perform the specified operation
    if operation == 'mean':
        return filtered_data[column].mean()
    elif operation == 'median':
        return filtered_data[column].median()
    elif operation == 'max':
        return filtered_data[column].max()
    elif operation == 'min':
        return filtered_data[column].min()
    elif operation == 'std':
        return filtered_data[column].std()
    else:
        return None

# Read the data
data = pd.read_csv('attention-data.csv')

# Test the function with different parameters
print(f"Mean test score: {advanced_attention_analysis(data):.2f}")
print(f"Median test score for attentive students: {advanced_attention_analysis(data, 'test_score', 'median', attention_label='Attentive')}")
print(f"Maximum phone duration for distracted students: {advanced_attention_analysis(data, 'phone_duration (sec)', 'max', attention_label='Distracted')}")
print(f"Minimum test score for students with phone duration > 40: {advanced_attention_analysis(data, operation='min', phone_duration_gt=40)}")

